// Some portions generated by Claude
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions, LayoutResult} from './graph-layout-engine.ts';
import {graphNodeSize} from './graph-geometry.ts';
import {layoutTopology} from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';

/** A terminal fan is not a community. Peel it before solving the connected
 * core, then reserve its angular territory and stagger terminal nodes over
 * bounded rings. Routing clears remaining spokes. No RDF edge is removed.
 */
export function computeHubNeighborhoodLayout(graph: Graph, options: LayoutOptions,
  solveCore: (graph: Graph) => LayoutResult): LayoutResult | undefined {
  if (options.incremental || options.refine || options.repairOnly || options.localNodeIds?.size ||
      options.groups?.length || options.nodeSizes || graph.nodes.some(n => n.pinned) || graph.nodes.length > 350) return;
  const topology = layoutTopology(graph);
  const candidates = topology.nodes().map(id => ({id, leaves: topology.neighbors(id).filter(n => topology.degree(n) === 1)}))
    .sort((a,b) => b.leaves.length - a.leaves.length || Number(a.id) - Number(b.id));
  const winner = candidates[0];
  if (!winner || winner.leaves.length < 24 || winner.leaves.length < graph.nodes.length * .55 ||
      winner.leaves.length === graph.nodes.length - 1) return;
  const root = graph.nodes[Number(winner.id)];
  const leafIds = new Set(winner.leaves.map(i => graph.nodes[Number(i)].id));
  // Self loops and parallel relations are not simple terminal spokes.
  const counts = new Map<string, number>();
  for (const e of graph.edges) for (const id of [e.source,e.target]) counts.set(id,(counts.get(id) ?? 0)+1);
  if ([...leafIds].some(id => counts.get(id) !== 1)) return;
  const core: Graph = {...graph, nodes: graph.nodes.filter(n => !leafIds.has(n.id)),
    edges: graph.edges.filter(e => !leafIds.has(e.source) && !leafIds.has(e.target))};
  if (core.nodes.length > 64) return;
  const solved = solveCore(core), origin = solved.positions.get(root.id)!;
  const positions = new Map<string, PointerPosition>([[root.id,{x:0,y:0}]]);
  // Reserve the left 90-degree wedge for the core, including card extents.
  // This moves a rigid neighborhood, not every node independently.
  let shift = 0;
  for (const n of core.nodes) if (n.id !== root.id) {
    const p = solved.positions.get(n.id)!, s = graphNodeSize(n);
    shift = Math.max(shift,p.x-origin.x+s.width/2+Math.abs(p.y-origin.y)+s.height/2+gap.groupGap);
  }
  for (const n of core.nodes) if (n.id !== root.id) {
    const p = solved.positions.get(n.id)!;
    positions.set(n.id,{x:p.x-origin.x-shift,y:p.y-origin.y});
  }
  const leaves = graph.nodes.filter(n => leafIds.has(n.id)).sort((a,b) => a.id.localeCompare(b.id));
  const sizes = leaves.map(graphNodeSize);
  const span = Math.PI * 1.5, start = -Math.PI * .75;
  // A single collision-free ring makes fit-to-view unusably sparse. Multiple
  // staggered rings balance footprint against the obstacle router's work.
  // Rectangle diagonals bound the tangential and radial clearance; the shared
  // final verifier remains authoritative for actual rectangle intersections.
  const rings = Math.max(1, Math.ceil(Math.sqrt(leaves.length / 12)));
  const stride = Math.max(...sizes.map(s=>Math.hypot(s.width+gap.nodeGapX,s.height+gap.nodeGapY)));
  let offset = 0;
  for(let ring=0;ring<rings;ring++) {
    const count = Math.ceil((leaves.length-offset)/(rings-ring));
    const r = Math.max(300, count*stride/span) + ring*stride;
    for(let k=0;k<count;k++) {
      const i=offset+k, a=start+(k+.5+(ring%2)*.25)/count*span;
      positions.set(leaves[i].id,{x:Math.cos(a)*r,y:Math.sin(a)*r});
    }
    offset+=count;
  }
  // Generic coordinate descent must not move the core across its reserved
  // wedge or erase the deliberately separated core/terminal regions.
  return {positions,bends:new Map(),protectedNodeIds:new Set(graph.nodes.map(n=>n.id))};
}
